// Writes src/api/generated/<service>.ts, the TypeScript types of the named schemas (components/schemas) of each backend
// contract the web app calls, from contracts/http/<service>.openapi.json (written by scripts/export_contracts.py).
// src/api/models.ts names the ones the app uses.
// With --check nothing is written: it lists every generated file that differs and exits 1 if any does.
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import openapiTS, { astToString } from 'openapi-typescript';
import prettier from 'prettier';

const SERVICES = [
  'identity',
  'curriculum',
  'content',
  'assessment',
  'grading',
  'analytics',
  'question-chatbot-agent',
  'question-generation-agent',
];
const contracts = new URL('../../../contracts/http/', import.meta.url);
const generated = new URL('../src/api/generated/', import.meta.url);
const check = process.argv.includes('--check');

const stale = [];
await mkdir(generated, { recursive: true });
for (const service of SERVICES) {
  const contract = JSON.parse(await readFile(new URL(`${service}.openapi.json`, contracts), 'utf8'));
  // Only the schemas: the app's clients name their own paths.
  const ast = await openapiTS({ ...contract, paths: {} }, { defaultNonNullable: false, silent: true });
  const header =
    `// Generated by \`npm run contracts\` from contracts/http/${service}.openapi.json. Do not edit: change the ` +
    'contract (scripts/export_contracts.py or the service) and run it again.\n\n';
  const target = new URL(`${service}.ts`, generated);
  const options = await prettier.resolveConfig(fileURLToPath(target));
  const text = await prettier.format(header + astToString(ast), {
    ...options,
    filepath: fileURLToPath(target),
  });
  if (!check) {
    await writeFile(target, text);
  } else if ((await readFile(target, 'utf8').catch(() => '')) !== text) {
    stale.push(`apps/web/src/api/generated/${service}.ts`);
  }
}
if (stale.length) {
  console.error(
    `Out of date; run npm run contracts in apps/web and review the diff:\n  ${stale.join('\n  ')}`,
  );
  process.exit(1);
}
console.log(`${check ? 'Checked' : 'Generated'} ${SERVICES.length} API type files.`);
